// Deliberately synthetic alias: ANCFZ-TEST-SC-2026-000001
// always maps to database-issued ANCFZ-SC-2026-000001, never a real licence.
const b=$input.first().json.body??{};
if(b.agentKey!=='ancfz'||typeof b.ticketId!=='string'||
   !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(b.ticketId)||
   typeof b.licenceNumber!=='string'||
   !/^ANCFZ-TEST-SC-[0-9]{4}-[0-9]{6}$/.test(b.licenceNumber))
  throw Error('Invalid synthetic licence alias');
return [{json:{contractNumber:b.licenceNumber.replace('ANCFZ-TEST-SC-','ANCFZ-SC-')}}];

const contractNumber=$('Validate Synthetic Licence').first().json.contractNumber;
const rows=$input.all().map(x=>x.json).filter(r=>r&&r.contractNumber===contractNumber);
const validId=x=>typeof x==='string'&&/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(x);
let result={status:'not_found'};
if(rows.length>1000)result={status:'review'};
else if(rows.length){
  const verified=rows.filter(r=>r.status==='verified_completed'&&validId(r.contractId)&&validId(r.ticketId)&&Number.isInteger(Number(r.revision))&&Number(r.revision)>=1);
  if(verified.length!==rows.length)result={status:'review'};
  else {
    verified.sort((a,b)=>Number(b.revision)-Number(a.revision));
    const latest=verified[0];
    if(verified.length>1&&Number(verified[1].revision)===Number(latest.revision))result={status:'review'};
    else result={status:'found',contractNumber,contractId:latest.contractId,ticketId:latest.ticketId,revision:Number(latest.revision)};
  }
}
return [{json:result}];
